/* Interactive local prototype. All grants, data and jobs in this file are explicitly demo-only. */
const DY=DouyinModel,dyState=DY.createState();
const dyUI={reportShop:'a-river',reportDate:dyYesterday(),reportSample:false,report:null,liveUrl:'',liveShop:'a-river',liveFrequency:'15',liveResult:null,liveSample:false,liveError:'',authKind:'douyin'};
function dyYesterday(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(Date.now()-86400000));const get=t=>parts.find(p=>p.type===t).value;return `${get('year')}-${get('month')}-${get('day')}`;}
function dyTime(t){return new Date(t).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});}
function dyOptions(items,value,empty){return (empty?`<option value="">${esc(empty)}</option>`:'')+items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x.name)}</option>`).join('');}
function dySaveSettings(){try{localStorage.setItem('wecar-douyin-demo-v1',JSON.stringify({grants:dyState.grants,configs:dyConfigs}));}catch{toast('浏览器无法保存设置；本页内仍可体验。')}}
let dyConfigs={};
try{const saved=JSON.parse(localStorage.getItem('wecar-douyin-demo-v1')||'{}');if(Array.isArray(saved.grants))dyState.grants=saved.grants.filter(g=>g.mode==='demo'&&Array.isArray(g.scopes)&&Array.isArray(g.shops)&&DY.catalog.tenants.some(t=>t.id===g.tenant));dyState.grants=dyState.grants.map(g=>({...g,scopes:g.scopes.filter(x=>DY.selectableScopes(g.kind).includes(x))}));if(saved.configs&&typeof saved.configs==='object')dyConfigs=saved.configs;}catch{}
function dyTenant(id){vClearMedia();DY.changeTenant(dyState,id);Object.assign(videoFlow,{request:'',prompt:'',files:[],phase:0,previewUrl:'',error:'',outputSample:false});const st=DY.shops(dyState)[0];Object.assign(dyUI,{reportShop:st.id,liveShop:st.id,report:null,reportSample:false,liveResult:null,liveUrl:'',liveError:''});render();}
function dyContext(){return `<div class="dy-context"><div><span class="dy-kicker">工作企业</span><select aria-label="抖音工作企业" onchange="dyTenant(this.value)">${dyOptions(DY.catalog.tenants,dyState.tenant)}</select></div><span class="dy-status">${icon('shield-check')} 示例环境 · 真实服务未连接</span><button class="link" onclick="navigate('authorize')">管理账号授权 →</button></div>`;}
function dyIntro(iconName,title,desc){return `<div class="dy-intro"><span class="dy-icon">${icon(iconName)}</span><div><h2>${title}</h2><p>${desc}</p></div></div>`;}
function dyEmpty(text){return `<div class="dy-empty">${icon('unplug')}<p>${text}</p></div>`;}
function dyLogs(){const logs=dyState.logs.filter(l=>l.tenant===dyState.tenant);return `<div class="dy-work">${dyContext()}<div class="dy-card"><h3>当前企业 · 操作记录</h3>${logs.length?logs.map(l=>`<div class="dy-log"><time>${dyTime(l.at)}</time><p>${esc(l.text)}</p></div>`).join(''):dyEmpty('还没有操作记录。所有记录均为本地演示操作。')}</div></div>`;}
function dyWorkspace(){if(tabName==='执行记录')return dyLogs();return `<div class="dy-work">${dyContext()}${current==='authorize'?dyAuthorization():current==='monitor'?dyDaily():dyLive()}</div>`;}
function dyAuthorization(){const own=dyState.grants.filter(g=>g.tenant===dyState.tenant),kind=dyUI.authKind;return `${dyIntro('key-round','先连接账号，让员工在授权范围内工作','两套应用分别申请能力，账号和商家分别授权；绑定门店不会自动获得发布权。')}<div class="dy-grid two"><div class="dy-card"><span class="dy-kicker">抖音账号</span><h3>授权发布账号</h3><p>发布能力需网站应用单独获批；视频指标通道待核验，通用直播数据已下线。</p><button class="primary" onclick="dyAuthDialog('douyin')">${icon('plus')} 连接抖音账号</button></div><div class="dy-card"><span class="dy-kicker">来客商家</span><h3>门店、商品与经营</h3><p>选择油站与商品、订单查询、验券记录范围。仅使用接口实际返回的商品和字段；油站评价能力尚未确认。</p><button class="primary" onclick="dyAuthDialog('laike')">${icon('plus')} 连接来客商家</button></div></div><div class="dy-card"><div class="dy-row"><h3>账号与资源</h3><span class="dy-tag">${own.filter(g=>g.active&&g.expires>Date.now()).length} 项示例授权</span></div>${own.length?own.map(g=>`<div class="dy-account"><div class="dy-row"><strong>${esc(g.name)}</strong><span class="dy-tag ${!g.active||g.expires<Date.now()?'warn':''}">${!g.active?'已撤销':g.expires<Date.now()?'已过期':'示例授权有效'}</span></div><p>${g.kind==='douyin'?'抖音账号':'来客商家'} · ${g.scopes.map(x=>dyScopeName(x)).join(' / ')||'未授予能力'}</p><small>门店：${DY.shops(dyState).filter(x=>g.shops.includes(x.id)).map(x=>x.name).join('、')||'无'} · 有效至 ${dyTime(g.expires)}</small><div class="dy-row actions"><button class="link" onclick="dyAuthDialog('${g.kind}','${g.id}')">调整范围 / 重新授权</button>${g.active?`<button class="link danger" onclick="dyRevoke('${g.kind}','${g.id}')">撤销示例授权</button>`:''}</div></div>`).join(''):dyEmpty('尚未连接账号。先体验授权，再开始门店创作。')}</div><details class="dy-card"><summary>授权如何完成</summary><p>正式接入后，从本后台发起授权，打开抖音 / 来客官方页面完成登录与同意，再回到这里展示结果。平台不会在本页索取抖音或来客密码。</p><p>发布、读取数据、商品挂载均需相应应用能力获批，并在服务端逐次校验账号和门店范围。示例授权只用于体验，不是真实平台凭证。</p></details>${dyBoundaryCard()}`;}
function dyScopeName(x){if(DY.policy[x])return DY.policy[x].label;return ({publish:'视频发布',video:'视频数据',live:'直播数据',goods:'商品读取',sales:'销售数据',verify:'核销数据',reviews:'评价数据'})[x]||'未知权限';}
function dyAuthDialog(kind,id=''){dyUI.authKind=kind;const entries=(kind==='douyin'?DY.catalog.accounts:DY.catalog.merchants).filter(x=>x.tenant===dyState.tenant);const scopes=kind==='douyin'?['publish','video','live']:['goods','sales','verify','reviews'];const g=dyState.grants.find(g=>g.id===id&&g.kind===kind&&g.tenant===dyState.tenant);modal(`<h2 id="modal-title">连接${kind==='douyin'?'抖音账号':'来客商家'}</h2><p>从此后台发起，授权将在官方页面完成。</p><div class="dy-soft"><strong>官方授权尚未配置</strong><p>等待网站应用 / 生活服务应用开通和服务端回调接入。当前不能完成真实授权。</p><button class="secondary" disabled>前往官方授权 · 待接入</button></div><h3>本地示例授权</h3><div class="field"><label for="dyAuthId">选择示例${kind==='douyin'?'账号':'商家'}</label><select id="dyAuthId">${dyOptions(entries,g?.id||entries[0].id)}</select></div><div class="dy-check-grid">${scopes.map(x=>`<label><input name="dyScope" type="checkbox" value="${x}" ${!DY.policy[x].selectable?'disabled':!g||g.scopes.includes(x)?'checked':''}>${dyScopeName(x)}</label>`).join('')}</div><p class="dy-caption">此处是产品演示分组，不是实际OAuth scope清单。真实授权项仅由应用获批能力和官方授权页决定；灰色项不可选择。</p><h4>授权门店范围</h4><div class="dy-check-grid">${DY.shops(dyState).map(x=>`<label><input name="dyShop" type="checkbox" value="${x.id}" ${!g||g.shops.includes(x.id)?'checked':''}>${x.name}</label>`).join('')}</div><label class="dy-check"><input id="dyDemoAuthAck" type="checkbox">我确认这是本地演示，不代表已获得真实账号权限。</label><div id="dyAuthError" role="alert" class="dy-inline-error"></div><button class="primary" onclick="dyConfirmAuth()">保存示例授权</button>`);}
function dyConfirmAuth(){if(!$('#dyDemoAuthAck').checked){$('#dyAuthError').textContent='请确认本地示例授权说明';return;}const scopes=[...document.querySelectorAll('[name="dyScope"]:checked')].map(x=>x.value),shops=[...document.querySelectorAll('[name="dyShop"]:checked')].map(x=>x.value);if(!scopes.length||!shops.length){$('#dyAuthError').textContent='至少选择一项能力和一家门店';return;}try{DY.demoAuthorize(dyState,dyUI.authKind,$('#dyAuthId').value,scopes,shops);dySaveSettings();dyUI.report=null;closeModal();render();toast('已保存本地示例授权；未向抖音提交授权');}catch(e){$('#dyAuthError').textContent=e.message;}}
function dyRevoke(kind,id){modal(`<h2 id="modal-title">撤销示例授权？</h2><p>该账号的后续发布和查询将被阻止，已有发布确认会失效。已保存的演示任务不会在外部执行。</p><button class="primary" onclick="dyConfirmRevoke('${kind}','${id}')">确认撤销</button>`);}
function dyConfirmRevoke(kind,id){DY.revoke(dyState,kind,id);dySaveSettings();dyUI.report=null;closeModal();render();}
function dyDaily(){const cfg=dyConfigs[dyState.tenant],r=dyUI.report;return `${dyIntro('notebook-pen','每天一份经营日报，先看需要处理的事','订单与验券可按授权汇总；直播、视频指标和油站差评不作默认可用承诺。')}<div class="dy-card"><div class="dy-toolbar"><div class="field"><label for="dyReportShop">门店范围</label><select id="dyReportShop" onchange="dyUI.reportShop=this.value;dyUI.report=null;render()">${dyOptions(DY.shops(dyState),dyUI.reportShop)}</select></div><div class="field"><label for="dyReportDate">日报日期 · 北京时间</label><input id="dyReportDate" type="date" max="${dyYesterday()}" value="${dyUI.reportDate}" onchange="dyUI.reportDate=this.value;dyUI.report=null;render()"></div><button class="primary" onclick="dyGenerateReport(false)">生成日报</button><button class="secondary" onclick="dyGenerateReport(true)">载入示例日报</button></div><p class="dy-caption">日报统计所选日 00:00–24:00；采集时间、归因口径及权限会影响可见数据。</p></div>${r?dyReportHtml(r):`<div class="dy-card">${dyEmpty('选择日期生成日报。尚未接入真实数据源，示例数据需要明确载入。')}</div>`}<div class="dy-card"><div class="dy-row"><h3>日报发送配置（本平台能力）</h3><span class="dy-tag warn">${cfg?'已保存配置 · 待连接':'未设置'}</span></div><p>调度与飞书/企微发送由本平台另行接入，不是抖音开放权限。仅发送获准用途、接收范围内的数据；延迟和缺项必须说明。</p><div class="dy-form-grid"><div class="field"><label for="dyPushTime">发送时间 · Asia/Shanghai</label><input id="dyPushTime" type="time" value="${esc(cfg?.time||'09:30')}"></div><div class="field"><label for="dyPushChannel">推送渠道</label><select id="dyPushChannel">${dyOptions([{id:'workspace',name:'工作台通知'},{id:'feishu',name:'飞书（待接入）'},{id:'wecom',name:'企业微信（待接入）'}],cfg?.channel||'workspace')}</select></div><div class="field"><label for="dyPushRecipient">接收范围</label><select id="dyPushRecipient"><option value="self">当前企业 · 我的工作台</option></select></div></div><label class="dy-check"><input type="checkbox" id="dyPushEnabled" ${cfg?.enabled?'checked':''}>希望每天推送日报</label><div class="dy-row"><small>此处保存配置草案；尚无后台调度或消息发送。</small><button class="primary" onclick="dySaveReportConfig()">保存推送配置</button></div>${cfg?`<p class="dy-caption">已保存：${esc(DY.shops(dyState).find(x=>x.id===cfg.shop)?.name||'门店已失效')} · ${esc(cfg.time)} · ${cfg.enabled?'期望启用，等待服务接入':'暂停推送'}；没有启动真实自动化。</p>`:''}</div>`;}
function dyGenerateReport(sample){if(!dyUI.reportDate||dyUI.reportDate>dyYesterday()||!/^\d{4}-\d{2}-\d{2}$/.test(dyUI.reportDate)){toast('请选择昨天或更早的有效日期');return;}dyUI.reportSample=sample;dyUI.report=DY.dailyReport(dyState,dyUI.reportShop,dyUI.reportDate,sample);DY.log(dyState,'生成'+(sample?'示例':'缺数状态')+'日报：'+dyUI.reportDate);render();}
function dyReportHtml(r){const available=r.metrics.filter(x=>x.value!==null).length;return `<div class="dy-card"><div class="dy-row"><h3>${r.date} · ${r.shop.name}</h3><span class="dy-tag">${dyUI.reportSample?'示例日报':'等待数据'}</span></div><p>当前可展示 ${available} / ${r.metrics.length} 类指标。${available?'当前仅展示有明确文档路径的订单及验券示例；其余能力保持不可用。':'未取得真实数据，不据此推断销售下滑或直播异常。'}</p><div class="dy-metrics">${r.metrics.map(m=>`<div><small>${m.name}</small><strong>${m.value||'—'}</strong><span>${m.status} · ${m.source}</span></div>`).join('')}</div><details><summary>指标口径与数据状态</summary>${r.metrics.map(m=>`<p><strong>${m.name}</strong>：${m.definition}；来源 ${m.source}；${m.status}。</p>`).join('')}<p>示例生成时间：${dyTime(new Date())}。真实数据同步时间未取得。成交与核销不能直接相减作为未核销余额。</p></details><h4>直播与视频</h4><p>${r.metrics[3].value?'直播场次 1 场、开播 2 小时、最高在线 86 人（均为示例）。真实直播取数与归因接口待核验。':'直播：通用直播数据接口已下线。小程序专用数据仅在另行接入对应小程序后评估，不能由网站账号授权替代。'}</p><p>${r.metrics[4].value?'视频：当日示例播放 12,840 次；点赞 286、评论 18、分享 34（示例）。仅统计授权账号作品；完整观看指标待接口确认。':'视频：网站应用指标通道待核验。已发布作品ID或基础信息不等于获得播放、完播或成交数据。'}</p><h4>差评内容与跟进</h4>${r.reviews?r.reviews.map(x=>`<blockquote>${esc(x.text)}<small>${x.rating}</small></blockquote><p>${x.action}</p>`).join(''):'<p>油站评价接口尚未确认；已查到的餐饮评价接口不直接适用。可由商家提供其有权使用的后台导出材料，不能显示为“无差评”。</p>'}<h4>今日注意事项</h4><ul><li>检查数据授权是否有效，补齐缺失数据后再判断经营变化。</li><li>核对商品在售状态、适用门店、有效期及使用条件。</li><li>直播风险提示需结合抽查证据复核，不代替平台处罚结论。</li></ul></div>`;}
function dySaveReportConfig(){const time=$('#dyPushTime').value;if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(time)){toast('请填写有效的推送时间');return;}dyConfigs[dyState.tenant]={time,channel:$('#dyPushChannel').value,recipient:'self',shop:dyUI.reportShop,enabled:$('#dyPushEnabled').checked,timezone:'Asia/Shanghai',mode:'draft'};DY.log(dyState,'保存日报推送配置草案；未启动调度或外部推送');dySaveSettings();render();toast('配置草案已保存，等待数据源和推送服务接入');}
const dyFactors=[['画面质量',['清晰度与稳定性','人物与景别','布景与主体关系','光线与曝光','贴片与文字可读性','声画与环境噪声']],['商品吸引力',['商品或服务展示','核心卖点说明','真实服务过程','权益与价格依据','适用门店与条件','讲品与答疑']],['主播专业度',['真人表达与镜头交流','形象与现场安全','讲解准确性','互动响应','开播时长（需后台）','分工与节奏']],['投流运营能力',['本地推（需后台）','短视频引流（需后台）','福利节点','商品与福利配合','活动配置证据','复盘与跟进记录']]];
function dyLive(){const tasks=dyState.liveTasks.filter(x=>x.tenant===dyState.tenant);return `${dyIntro('scan-eye','登记直播间，基于有权使用的证据诊断','不根据一个直播链接自动获取直播流；先确认素材来源，再做四维复核。')}<div class="dy-card"><div class="field"><label for="dyLiveUrl">直播链接或 room_id</label><input id="dyLiveUrl" value="${esc(dyUI.liveUrl)}" oninput="dyLiveInput(this.value)" placeholder="https://live.douyin.com/… 或抖音直播分享短链"></div><div class="dy-form-grid"><div class="field"><label for="dyLiveShop">关联门店</label><select id="dyLiveShop" onchange="dyUI.liveShop=this.value;dyUI.liveResult=null;render()">${dyOptions(DY.shops(dyState),dyUI.liveShop)}</select></div><div class="field"><label for="dyLiveFrequency">自动回扫 · 未确认支持</label><select disabled id="dyLiveFrequency" onchange="dyUI.liveFrequency=this.value">${dyOptions([{id:'5',name:'每 5 分钟'},{id:'15',name:'每 15 分钟'},{id:'30',name:'每 30 分钟'}],dyUI.liveFrequency)}</select></div></div><div class="dy-inline-error" role="alert">${esc(dyUI.liveError)}</div><div class="dy-row actions"><button class="primary" disabled title="未确认适用的官方直播采集接口">${icon('radar')} 自动回扫不可用</button><button class="secondary" onclick="dyInspect(false)">检查证据状态</button><button class="link" onclick="dyInspect(true)">体验示例诊断</button></div><p class="dy-caption">未找到适用本网站应用的公开直播拉流/录制接口；通用直播数据已下线。不会通过非官方接口或抓包绕过。可另行提供有权使用的录屏/截图做辅助诊断。</p></div>${tasks.length?`<div class="dy-card"><h3>巡检方案</h3>${tasks.map(t=>`<div class="dy-account"><div class="dy-row"><strong>${esc(DY.shops(dyState).find(x=>x.id===t.shop)?.name)}</strong><span class="dy-tag">${t.paused?'已暂停':'待采集服务'}</span></div><p>${esc(t.url)} · 每 ${t.frequency} 分钟</p><button class="link" onclick="dyToggleLive('${t.id}')">${t.paused?'恢复方案':'暂停方案'}</button><small> · 已执行真实抽查 0 次</small></div>`).join('')}</div>`:''}<div id="dyLiveResult">${dyUI.liveResult?dyLiveResult():''}</div><details class="dy-card" open><summary>判定依据与版本</summary><p>四维 24 项为内部诊断清单，参考既有直播诊断技能；不把内部质量建议直接视为抖音官方违规阈值。官方最新完整版本尚待同步核验。</p><p>参考核查日期：2026-10-24。<a href="https://lifexue.com/rule/detail/406305797378?enter_method=rule_page&from=list" target="_blank" rel="noopener">生活服务学习中心规则</a> · <a href="https://sf3-cdn-tos.douyinstatic.com/obj/ies-hotsoon-draft/webcast_all_anchor/webcast_ban_protocol.html" target="_blank" rel="noopener">直播行为规范</a></p><div class="dy-factor-grid">${dyFactors.map(([title,items])=>`<div><strong>${title}</strong><ul>${items.map(x=>'<li>'+x+'</li>').join('')}</ul></div>`).join('')}</div><p>静态帧只能辅助判断画面和部分商品信息；声音、互动、时长和投流需要录屏、授权后台或运营配置证据。未知项保持“需核验”。</p></details>`;}
function dyLiveInput(value){dyUI.liveUrl=value;dyUI.liveResult=null;const result=$('#dyLiveResult');if(result)result.innerHTML='';}
function dyLiveValidate(){const v=dyUI.liveUrl.trim();if(!DY.validLiveUrl(v)){dyUI.liveError='请填写 HTTPS 抖音直播链接、抖音分享短链或有效 room_id。';render();return false;}dyUI.liveError='';return true;}
function dyCreateLive(){if(!dyLiveValidate())return;toast('未确认官方直播采集通道，不能启动自动回扫');}
function dyToggleLive(id){const task=dyState.liveTasks.find(x=>x.id===id&&x.tenant===dyState.tenant);if(task){task.paused=!task.paused;DY.log(dyState,(task.paused?'暂停':'恢复')+'本地巡检方案；未运行外部采集');render();}}
function dyInspect(sample){if(!dyLiveValidate())return;dyUI.liveSample=sample;dyUI.liveResult={...DY.liveAssessment(sample),url:dyUI.liveUrl.trim(),shop:dyUI.liveShop};DY.log(dyState,sample?'查看直播诊断示例；非所填链接的真实检测结果':'检查直播证据：未确认官方采集通道，结果为需补充核验');render();}
function dyLiveResult(){const r=dyUI.liveResult;return `<div class="dy-card"><div class="dy-row"><h3>抽查结果</h3><span class="dy-tag warn">${r.level}</span></div><p class="dy-caption">关联链接：${esc(r.url)} · ${esc(DY.shops(dyState).find(x=>x.id===r.shop)?.name)}</p><p>${dyUI.liveSample?'以下为独立的示例诊断，不代表所填直播间的真实表现。':'没有该直播间有权使用的画面或声音证据；不根据链接抓流，不生成达标或违规结论。'}</p><div class="dy-evidence">${r.dimensions.map(x=>`<div><strong>${x.name}</strong><span class="dy-tag">${x.status}</span><p>${x.evidence}</p></div>`).join('')}</div><h4>P0 · 优先处理</h4><p>${dyUI.liveSample?'示例：核实并补充商品适用门店、使用条件；移开遮挡商品的贴片。未发现真实证据前不认定违规。':'由商家提供有权使用的当前录屏或截图，并核对规则适用范围后，再做人工辅助诊断。'}</p><h4>P1 · 优化建议</h4><p>检查人物景别和商品展示；讲解权益时同步说明限制条件；投流与开播时长补充后台依据。</p><h4>抽查证据</h4><p>${dyUI.liveSample?'示例证据说明：画面 A 为贴片遮挡，画面 B 为条件缺失；无真实截图或录屏。':'无可用证据；未截帧、未录音。'}</p><p class="dy-caption">查看时间 ${dyTime(new Date())} · 官方规则版本待核验 · 系统建议需人工复核。</p></div>`;}
function renderDouyinRight(){const counts=dyState.grants.filter(g=>g.tenant===dyState.tenant&&g.active&&g.expires>Date.now()).length;$('#right').innerHTML=`<div class="right-head"><div class="right-title">抖音员工 <span>经营协作</span></div></div><div class="panel"><div class="dy-kicker">DOUYIN / WORKSPACE</div><h2>${current==='video'?'从需求开始，把内容做好':'让创作和经营连起来'}</h2><p>授权范围跟随账号和门店，确认后的内容才进入发布任务。</p><div class="dy-side-item">${icon('key-round')}<div>分渠道授权<small>${counts} 项有效示例授权，非真实凭证</small></div></div><div class="dy-side-item">${icon('messages-square')}<div>说需求，员工先整理<small>预填简报，保留不想要的内容</small></div></div><div class="dy-side-item">${icon('send')}<div>确认后发布<small>账号与POI核对，商品仅选品参考</small></div></div><div class="dy-side-item">${icon('notebook-pen')}<div>日报与直播素材诊断<small>未确认指标不开放；不自动抓流</small></div></div><div class="dy-soft">当前为本地交互原型。示例授权可保存在本浏览器；真实授权凭证必须由后端安全管理。</div></div><div class="panel-actions"><button class="secondary" onclick="navigate('authorize')">查看账号授权</button></div>`;}

function dyBoundaryCard(){return `<details class="dy-card"><summary>抖音能力边界 · 2026-10-24复核</summary><p>有文档不等于本应用已获批。有账号授权也不等于拥有所有数据；正式接入需以当前控制台、适用行业、官方授权结果和联调返回值共同核验。</p><ul><li>网站应用：video.create.bind 须独立申请；旧服务商控制台代发能力已下线。</li><li>来客：门店、商品、订单、验券按解决方案分别申请，不能合并成一个无限权限。</li><li>视频播放与互动：网站指标通道待核验，不使用旧文档或小程序接口代替。</li><li>直播：通用数据已下线；未确认网站应用有直播拉流/录制接口，自动回扫禁用。</li><li>商品挂载及油站评价：未确认适用，禁用；只作选品参考或由商家另行提供有权使用的材料。</li></ul><p><a href="https://developer.open-douyin.com/forum/bulletin/post/66cd430b73a9173bf14f8c66" target="_blank" rel="noopener">直播数据下线公告</a> · <a href="https://developer.open-douyin.com/docs/resource/zh-CN/dop/develop/openapi/video-management/douyin/create-video/video-create" target="_blank" rel="noopener">视频创建条件</a></p></details>`;}
